  async getFiledata(mdl: filedataReq): Promise<filedataRes> {
    const cacheKey = `${(mdl as any)?.nCaseid ?? ''}::${(mdl as any)?.cTab ?? ''}`;
    const cached = this.filedataCache.get(cacheKey);
    if (cached) return cached;

    const promise = (async (): Promise<filedataRes> => {
      try {
        let params = new HttpParams();
        for (const key in mdl) {
          if (mdl.hasOwnProperty(key)) {
            params = params.set(key, mdl[key]);
          }
        }
        const res: any = await firstValueFrom(
          this.http.get<filedataRes[]>(
            `${environment.cloudUrl}${environment.coreservice}/bundles/filedata`,
            { params: params }
          )
        );

        const result: filedataRes = res?.length ? res[0] : null;
        // Warm the browser's HTTP cache for the actual PDF binary URL. The
        // viewer iframe later issues the same GET — with the cache primed it
        // resolves instantly instead of stalling at "0% progress".
        if (result?.cPath) this.prefetchPdfBinary(result.cPath);
        return result;
      } catch (err: unknown) {
        this.tost.error(ErrorHandlerUtil.getErrorMessage(err));
        // Evict on error so a subsequent attempt can re-try cleanly.
        this.filedataCache.delete(cacheKey);
        return null;
      }
    })();

    this.filedataCache.set(cacheKey, promise);
    return promise;
  }

  // Dedupe so we don't refetch the same PDF binary twice in a session.
  private prefetchedBinaries = new Set<string>();

  private prefetchPdfBinary(cPath: string): void {
    try {
      if (!cPath || this.prefetchedBinaries.has(cPath)) return;
      this.prefetchedBinaries.add(cPath);
      // Fire a GET in the background. `mode: 'no-cors'` keeps cross-origin
      // PDF hosts happy — we don't need the response body, only the cache
      // entry. Same-origin URLs work the same way. Errors are swallowed —
      // the click-time fetch inside the iframe still works without us.
      fetch(cPath, {
        method: 'GET',
        mode: 'no-cors',
        credentials: 'include',
        cache: 'force-cache',
      }).catch(() => { /* non-critical */ });
    } catch {
      // non-critical
    }
  }

