  async downloadFiles(nCaseid: string, nSectionid: string, jFiles: string, jFolders: string, nDTaskid: string): Promise<1 | 2 | 0> {
    const nUserid = await this.sStore.getUserId();
    const sizeDetail: { msg: 1 | -1, cFinalSize: number, isValidForStream: boolean } = await this.downloadService.getApproximateUrl({ nCaseid, nSectionid, jFiles, jFolders, nMasterid: nUserid, isHyperlink: false });

    if (sizeDetail.isValidForStream || environment.name === 'localdocker') {
      const link = document.createElement('a');
      link.href = `${environment.downloadservice}/download/downloadfile?nCaseid=${nCaseid}&nSectionid=${nSectionid}&jFiles=${jFiles}&jFolders=${jFolders}&nMasterid=${nUserid}&nDTaskid=${nDTaskid || null}`;
      link.setAttribute('download', ('folder'));

      document.body.appendChild(link);
      link.click();
      link.remove();
      return 1;
    } else {
      const res = await this.downloadService.downloadFiles({ nCaseid, nSectionid, jFiles, jFolders, isHyperlink: false });
      return (res?.msg === 1) ? 2 : 0;
    }
  }

